  circ = circ--sphericaltorectangular(1,t,30);
}

draw(circ,red);
draw((0,0,0)--(1,0,0),Arrow3(6));
draw((0,0,0)--(0,1,0),Arrow3(6));
draw((0,0,0)--(0,0,1),Arrow3(6));
draw(surface(O--P--(P.x,P.y,0)--cycle),gray(0.7),nolight);
