draw((0,0,0.5)..sphericaltorectangular(0.5,60,15)..sphericaltorectangular(0.5,60,30),Arrow3(6));
draw((0.4,0,0)..sphericaltorectangular(0.4,30,90)..sphericaltorectangular(0.4,60,90),Arrow3(6));

label("$x$", (1.1,0,0));
label("$y$", (0,1.1,0));
label("$z$", (0,0,1.1));
label("$\phi$", (0.2,0.2,0.6));
